                        trie_pool[node].add(val, 1)
            for k, idx in node_queries[node]:
                if trie_pool[node].count < k:
                    result[idx] = -1
                else:
                    result[idx] = trie_pool[node].find_kth(k)

        dfs(0)
        return result

